from lib import *
S = SS('l15')
steps = [
    step("gc 后 3000 个小文件的仓库只有一个 pack,它的 .idx 文件 85,968 字节:魔数 ff 74 4f 63(\\377tOc)、版本 2,接着是 256 项 fanout 表(每项 4 字节),所以对象数就是 fanout[255] = 3,032。各段范围:fanout [8,1032)、hash 表 [1032,61672)、crc 表 [61672,73800)、offset 表 [73800,85928),末尾 40 字节两个校验和;4 + 4 + 1024 + 3032×28 + 40 = 85,968,和文件大小完全一致。", t=tl(S(1)), mark=lidx(S(1), '魔数', '对象数(fanout[255])', '85,968(与文件大小一致'), done=lidx(S(1), '0000  ff 74 4f 63', '各段字节范围'), kv=KV([['魔数 + 版本', 'ff 74 4f 63 + 2'], ['fanout', '256 × 4 字节,最后一项是对象总数'], ['每个对象', '20 字节 hash + 4 字节 crc + 4 字节偏移'], ['末尾', 'pack 校验和 + idx 校验和']], ['fanout'])),
    step("fanout[i] 是第一个字节 ≤ i 的对象的累计个数:fanout[0x00]=9,fanout[0x01]=20(该档 11 个),fanout[0xff]=3,032 就是总数。hash 表按 hash 升序排列(验证为 True),用 hash 表重新数出的累计值与 fanout 全部一致。256 档的对象数最少 4、最多 23,平均 11.8——hash 分布得很均匀。", t=tl(S(2)), mark=lidx(S(2), 'fanout[0xff]', '256 档的对象数'), done=lidx(S(2), '升序排列', '全部一致', 'fanout[0x00]', 'fanout[0x01]'), kv=KV([['fanout[i]', '第一个字节 ≤ i 的对象数(累计)'], ['hash 表', '升序排列'], ['每档大小', '4 ~ 23,平均 11.8']], ['fanout[i]'])),
    step("手工查一个对象 4102105e…:第一个字节 0x41,fanout[0x40]=773、fanout[0x41]=786,把候选范围圈到下标 [773, 786) 共 13 个,再二分:第 1 次比较下标 779(大于目标),第 2 次下标 776(大于),第 3 次下标 774(大于),第 4 次下标 773,相等。再去 offset 表取下标 773 的值 37542,与 git verify-pack 给出的偏移 37542 一致。", t=tl(S(3)), mark=lidx(S(3), '第 1 次比较', '第 2 次比较', '第 3 次比较', '第 4 次比较'), done=lidx(S(3), '候选范围', '37542'), b=bars([['整张表', 3032, '3,032 个候选'], ['fanout 圈出的范围', 13, '13 个候选']], 3032, mark=[1], done=[0]), kv=KV([['第一步', '第一个字节 → fanout 圈范围'], ['第二步', '范围内二分查找'], ['第三步', '下标 → offset 表 → pack 偏移']], ['第一步'])),
    step("对全部 3,032 个对象各查一次统计比较次数:不用 fanout、整张 hash 表做二分,平均 10.65 次、最多 12 次(log2(3032) = 11.57);用 fanout 先圈范围再二分,平均 3.10 次、最多 5 次。fanout 把比较次数减少了约 71%,代价只是 1 KB 的表。", t=tl(S(4)), mark=lidx(S(4), '用 fanout 圈范围再二分'), done=lidx(S(4), '不用 fanout', 'N=3032'), b=bars([['不用 fanout(平均)', 10.65, '10.65 次'], ['用 fanout(平均)', 3.10, '3.10 次']], 10.65, mark=[1], done=[0]), kv=KV([['整表二分', '平均 10.65 次'], ['fanout + 二分', '平均 3.10 次,最多 5 次'], ['代价', '1 KB 的 fanout 表']], ['fanout + 二分'])),
    step("尾部:idx 倒数第 40~21 字节是 pack 文件的 SHA-1(9e4d0c9…),与 pack 文件最后 20 字节完全相同,idx 和 pack 靠它配对;idx 最后 20 字节是它自己前面全部内容的 SHA-1(4add1e1…),重新计算一致。crc 表:取 pack 偏移 262 的那个条目的原始字节算 CRC32 得到 15673c87,idx 的 crc 表里这一项也是 15673c87,pack 数据可以不解压就检查是否损坏。", t=tl(S(5)), mark=lidx(S(5), 'CRC32 = 15673c87'), done=lidx(S(5), 'idx 倒数第 40~21 字节', 'pack 文件最后 20 字节', 'idx 最后 20 字节', '重新算 idx'), kv=KV([['pack 校验和', 'idx 里记一份,用来配对'], ['idx 校验和', '最后 20 字节'], ['crc 表', '每个条目原始数据的 CRC32']], ['pack 校验和'])),
]
A = mkarti('l15', 15, 'Git,packfile,idx,fanout,二分查找,真实验证,动画演示',
    '用 Python 解析真实的 .idx(v2)文件:魔数、256 项 fanout 表、升序 hash 表、crc 表与 offset 表;手工用 fanout 圈范围再二分查找一个对象,偏移与 git verify-pack 一致;对 3,032 个对象平均比较次数从整表二分的 10.65 降到 3.10;尾部校验和与 crc 逐项验证。',
    '.idx 文件让 git 不用扫描整个 pack 就能找到一个对象。这篇把它拆开:魔数与版本、256 项 fanout 表怎么把查找范围缩小、手工二分查找一个 hash、与整表二分比平均省多少次比较,以及尾部的两个校验和和 crc 表。',
    [('3.10 vs 10.65', '3,032 个对象里,用 fanout 先圈范围再二分的平均比较次数,对比整表二分'), ('1 KB', 'fanout 表的大小:256 项 × 4 字节'), ('85,968 字节', '3,032 个对象的 .idx 文件大小,= 8 + 1024 + 28 × 3032 + 40')],
    [('布局', '<p>v2 的 .idx 依次是:魔数 <code>\\377tOc</code>、版本号 2、256 项 fanout 表、对象 hash 表(按升序)、每个对象的 CRC32 表、每个对象在 pack 里的偏移表(超过 2 GB 的偏移走 64 位表)、pack 的 SHA-1、idx 自己的 SHA-1。每个对象在 idx 里占 28 字节。</p>'),
     ('fanout 表', '<p><code>fanout[i]</code> 是 hash 第一个字节不超过 i 的对象个数,最后一项就是对象总数。hash 近似均匀分布,所以每一档大小接近(本例 4~23 个,平均 11.8)。</p>'),
     ('查找', '<p>用 hash 的第一个字节从 fanout 查到一段范围 <code>[fanout[b-1], fanout[b])</code>,只在这一段里二分;找到下标后,在偏移表同一下标取出 pack 里的位置。</p>'),
     ('省多少', '<p>3,032 个对象,整表二分平均 10.65 次比较,用 fanout 平均只要 3.10 次,最多 5 次。代价是多存一张 1 KB 的表。对象越多,整表二分的步数越大(log N),fanout 把查找范围先缩小 256 倍左右。</p>'),
     ('校验', '<p>idx 同时记着 pack 的校验和(与 pack 文件末尾相同,用于配对)和自己的校验和;crc 表让复用 pack 里的原始数据(比如 fetch 时)时不用解压就能检查数据是否损坏。</p>')],
    steps,
    [ENV_I_GIT + '。仓库是 3000 个很小的文件加 git gc 之后的单个 pack(3,032 个对象:3,000 个 blob、31 个 tree、1 个 commit);.idx 由我用 Python 按字节解析(ll.py 外,实验脚本内),对账对象是 git verify-pack -v 和 pack 文件末尾',
     '没有验证:超过 2 GB 的 pack 的 64 位偏移表;idx 版本 1(已淘汰);multi-pack-index 与 reverse index(.rev,后面单独一篇讲 multi-pack-index);hash 分布不均匀时 fanout 的退化;SHA-256 仓库的 idx(hash 长 32 字节)'],
    '.idx 与 fanout')
